# ! [doc = " Composable asynchronous iteration."] # ! [doc = ""] # ! [doc = " If you've found yourself with an asynchronous collection of some kind,"] # ! [doc = " and needed to perform an operation on the elements of said collection,"] # ! [doc = " you'll quickly run into 'async iterators'. Async Iterators are heavily used in"] # ! [doc = " idiomatic asynchronous Rust code, so it's worth becoming familiar with them."] # ! [doc = ""] # ! [doc = " Before explaining more, let's talk about how this module is structured:"] # ! [doc = ""] # ! [doc = " # Organization"] # ! [doc = ""] # ! [doc = " This module is largely organized by type:"] # ! [doc = ""] # ! [doc = " * [Traits] are the core portion: these traits define what kind of async iterators"] # ! [doc = "   exist and what you can do with them. The methods of these traits are worth"] # ! [doc = "   putting some extra study time into."] # ! [doc = " * Functions provide some helpful ways to create some basic async iterators."] # ! [doc = " * Structs are often the return types of the various methods on this"] # ! [doc = "   module's traits. You'll usually want to look at the method that creates"] # ! [doc = "   the `struct`, rather than the `struct` itself. For more detail about why,"] # ! [doc = "   see '[Implementing Async Iterator](#implementing-async-iterator)'."] # ! [doc = ""] # ! [doc = " [Traits]: #traits"] # ! [doc = ""] # ! [doc = " That's it! Let's dig into async iterators."] # ! [doc = ""] # ! [doc = " # Async Iterators"] # ! [doc = ""] # ! [doc = " The heart and soul of this module is the [`AsyncIterator`] trait. The core of"] # ! [doc = " [`AsyncIterator`] looks like this:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # use core::task::{Context, Poll};"] # ! [doc = " # use core::pin::Pin;"] # ! [doc = " trait AsyncIterator {"] # ! [doc = "     type Item;"] # ! [doc = "     fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>>;"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Unlike `Iterator`, `AsyncIterator` makes a distinction between the [`poll_next`]"] # ! [doc = " method which is used when implementing an `AsyncIterator`, and a (to-be-implemented)"] # ! [doc = " `next` method which is used when consuming an async iterator. Consumers of `AsyncIterator`"] # ! [doc = " only need to consider `next`, which when called, returns a future which"] # ! [doc = " yields `Option<AsyncIterator::Item>`."] # ! [doc = ""] # ! [doc = " The future returned by `next` will yield `Some(Item)` as long as there are"] # ! [doc = " elements, and once they've all been exhausted, will yield `None` to indicate"] # ! [doc = " that iteration is finished. If we're waiting on something asynchronous to"] # ! [doc = " resolve, the future will wait until the async iterator is ready to yield again."] # ! [doc = ""] # ! [doc = " Individual async iterators may choose to resume iteration, and so calling `next`"] # ! [doc = " again may or may not eventually yield `Some(Item)` again at some point."] # ! [doc = ""] # ! [doc = " [`AsyncIterator`]'s full definition includes a number of other methods as well,"] # ! [doc = " but they are default methods, built on top of [`poll_next`], and so you get"] # ! [doc = " them for free."] # ! [doc = ""] # ! [doc = " [`Poll`]: super::task::Poll"] # ! [doc = " [`poll_next`]: AsyncIterator::poll_next"] # ! [doc = ""] # ! [doc = " # Implementing Async Iterator"] # ! [doc = ""] # ! [doc = " Creating an async iterator of your own involves two steps: creating a `struct` to"] # ! [doc = " hold the async iterator's state, and then implementing [`AsyncIterator`] for that"] # ! [doc = " `struct`."] # ! [doc = ""] # ! [doc = " Let's make an async iterator named `Counter` which counts from `1` to `5`:"] # ! [doc = ""] # ! [doc = " ```no_run"] # ! [doc = " #![feature(async_iterator)]"] # ! [doc = " # use core::async_iter::AsyncIterator;"] # ! [doc = " # use core::task::{Context, Poll};"] # ! [doc = " # use core::pin::Pin;"] # ! [doc = ""] # ! [doc = " // First, the struct:"] # ! [doc = ""] # ! [doc = " /// An async iterator which counts from one to five"] # ! [doc = " struct Counter {"] # ! [doc = "     count: usize,"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " // we want our count to start at one, so let's add a new() method to help."] # ! [doc = " // This isn't strictly necessary, but is convenient. Note that we start"] # ! [doc = " // `count` at zero, we'll see why in `poll_next()`'s implementation below."] # ! [doc = " impl Counter {"] # ! [doc = "     fn new() -> Counter {"] # ! [doc = "         Counter { count: 0 }"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " // Then, we implement `AsyncIterator` for our `Counter`:"] # ! [doc = ""] # ! [doc = " impl AsyncIterator for Counter {"] # ! [doc = "     // we will be counting with usize"] # ! [doc = "     type Item = usize;"] # ! [doc = ""] # ! [doc = "     // poll_next() is the only required method"] # ! [doc = "     fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {"] # ! [doc = "         // Increment our count. This is why we started at zero."] # ! [doc = "         self.count += 1;"] # ! [doc = ""] # ! [doc = "         // Check to see if we've finished counting or not."] # ! [doc = "         if self.count < 6 {"] # ! [doc = "             Poll::Ready(Some(self.count))"] # ! [doc = "         } else {"] # ! [doc = "             Poll::Ready(None)"] # ! [doc = "         }"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # Laziness"] # ! [doc = ""] # ! [doc = " Async iterators are *lazy*. This means that just creating an async iterator doesn't"] # ! [doc = " _do_ a whole lot. Nothing really happens until you call `poll_next`. This is"] # ! [doc = " sometimes a source of confusion when creating an async iterator solely for its side"] # ! [doc = " effects. The compiler will warn us about this kind of behavior:"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = " warning: unused result that must be used: async iterators do nothing unless polled"] # ! [doc = " ```"] use split_decls_genesis :: ourprelude :: * ; mod async_iter ; mod from_iter ; pub use async_iter :: { AsyncIterator , IntoAsyncIterator } ; pub use from_iter :: { FromIter , from_iter } ;